#import <Foundation/Foundation.h>
#import "../RWDiscoveryMetadataPolicy.h"
int main(int argc,const char **argv){@autoreleasepool{if(argc!=3)return 2;NSDictionary *input=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:@(argv[1])] options:0 error:nil];NSMutableDictionary *titles=[NSMutableDictionary new];NSDictionary *labels=input[@"labels"],*catalog=input[@"catalog"];
 for(NSDictionary *entity in [input[@"entities"]allValues])for(NSString *imdb in catalog){NSDictionary *record=[RWDiscoveryMetadataPolicy recordForEntity:entity imdb:imdb labels:labels];if(!record)continue;NSMutableDictionary *m=[record mutableCopy];NSDictionary *show=input[@"tvmaze"][imdb];if([show[@"externals"][@"imdb"]isEqual:imdb]&&[show[@"language"]length]){m[@"primaryLanguage"]=[show[@"language"]isEqual:@"English"]?@"en":show[@"language"];m[@"languageSource"]=show[@"url"];}m[@"fetchedAt"]=@(NSDate.date.timeIntervalSince1970);titles[imdb]=m;}
 NSDictionary *output=@{@"version":@1,@"titles":titles};NSData *data=[NSJSONSerialization dataWithJSONObject:output options:0 error:nil];if(![data writeToFile:@(argv[2]) atomically:YES])return 1;NSMutableDictionary *groups=[NSMutableDictionary new];NSUInteger named=0;for(NSDictionary *m in titles.allValues){NSString *group=[RWDiscoveryMetadataPolicy languageGroup:m];groups[group]=@([groups[group]integerValue]+1);for(NSString *field in @[@"cast",@"directors",@"studios"])for(NSDictionary *ref in m[field])if([ref[@"name"]length])named++;}printf("%s\n",[[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:@{@"titles":@(titles.count),@"languageGroups":groups,@"namedCredits":@(named),@"bytes":@(data.length)} options:0 error:nil]encoding:NSUTF8StringEncoding].UTF8String);return 0;}}
